/**
 * LeftToolbar
 * Vertical icon strip combining bottom-toolbar + right-toolbar tools.
 * Pure HTML/CSS, same event wiring as original.
 */

import { Events } from '../events';
import { ShortcutManager } from '../shortcut-manager';
import { localize } from '../ui/localization';
import { createToolButton, createSeparator, blockPointerEvents } from './dom-helpers';
import { TooltipSystem } from './tooltip-system';
import {
    iconRectSelect, iconLassoSelect, iconPolygonSelect,
    iconBrushSelect, iconFloodSelect, iconEyedropper,
    iconSphereSelect, iconBoxSelect, iconRuler,
    iconSplatModeOn, iconSplatModeOff, iconShowHideSplats,
    iconCameraFrame, iconCameraReset,
    iconColorPanel, iconOptions
} from './icons';

class LeftToolbar {
    dom: HTMLDivElement;

    constructor(events: Events, tooltips: TooltipSystem, container: HTMLDivElement) {
        this.dom = container;

        const toolbar = container;
        blockPointerEvents(toolbar);

        const shortcutManager: ShortcutManager = events.invoke('shortcutManager');

        const tip = (localeKey: string, shortcutId?: string): string => {
            const text = localize(localeKey);
            if (shortcutId) {
                const s = shortcutManager.formatShortcut(shortcutId);
                if (s) return `${text} ( ${s} )`;
            }
            return text;
        };

        // === Selection Tools ===
        const picker = createToolButton({ icon: iconRectSelect, parent: toolbar });
        const lasso = createToolButton({ icon: iconLassoSelect, parent: toolbar });
        const polygon = createToolButton({ icon: iconPolygonSelect, parent: toolbar });
        const brush = createToolButton({ icon: iconBrushSelect, parent: toolbar });
        const flood = createToolButton({ icon: iconFloodSelect, parent: toolbar });
        const eyedropper = createToolButton({ icon: iconEyedropper, parent: toolbar });

        picker.addEventListener('click', () => events.fire('tool.rectSelection'));
        lasso.addEventListener('click', () => events.fire('tool.lassoSelection'));
        polygon.addEventListener('click', () => events.fire('tool.polygonSelection'));
        brush.addEventListener('click', () => events.fire('tool.brushSelection'));
        flood.addEventListener('click', () => events.fire('tool.floodSelection'));
        eyedropper.addEventListener('click', () => events.fire('tool.eyedropperSelection'));

        tooltips.register(picker, tip('tooltip.bottom-toolbar.rect', 'tool.rectSelection'), 'right');
        tooltips.register(lasso, tip('tooltip.bottom-toolbar.lasso', 'tool.lassoSelection'), 'right');
        tooltips.register(polygon, tip('tooltip.bottom-toolbar.polygon', 'tool.polygonSelection'), 'right');
        tooltips.register(brush, tip('tooltip.bottom-toolbar.brush', 'tool.brushSelection'), 'right');
        tooltips.register(flood, tip('tooltip.bottom-toolbar.flood', 'tool.floodSelection'), 'right');
        tooltips.register(eyedropper, tip('tooltip.bottom-toolbar.eyedropper', 'tool.eyedropperSelection'), 'right');

        createSeparator(toolbar);

        // === Volume Tools ===
        const sphere = createToolButton({ icon: iconSphereSelect, parent: toolbar });
        const box = createToolButton({ icon: iconBoxSelect, parent: toolbar });
        const ruler = createToolButton({ icon: iconRuler, parent: toolbar });

        sphere.addEventListener('click', () => events.fire('tool.sphereSelection'));
        box.addEventListener('click', () => events.fire('tool.boxSelection'));
        ruler.addEventListener('click', () => events.fire('tool.distanceMeasurement'));

        tooltips.register(sphere, tip('tooltip.bottom-toolbar.sphere'), 'right');
        tooltips.register(box, tip('tooltip.bottom-toolbar.box'), 'right');
        tooltips.register(ruler, 'Distance Measurement', 'right');

        createSeparator(toolbar);

        // === Camera Controls (from right-toolbar) ===
        // Mode toggle (centers/rings)
        const modeToggle = createToolButton({ icon: iconSplatModeOff, parent: toolbar });

        modeToggle.addEventListener('click', () => {
            events.fire('camera.toggleMode');
            events.fire('camera.setOverlay', true);
        });

        tooltips.register(modeToggle, tip('tooltip.right-toolbar.splat-mode', 'camera.toggleMode'), 'right');

        // Show/Hide splats
        const showHide = createToolButton({ icon: iconShowHideSplats, active: true, parent: toolbar });
        showHide.addEventListener('click', () => events.fire('camera.toggleOverlay'));
        tooltips.register(showHide, tip('tooltip.right-toolbar.show-hide', 'camera.toggleOverlay'), 'right');

        createSeparator(toolbar);

        // Camera frame & reset
        const cameraFrame = createToolButton({ icon: iconCameraFrame, parent: toolbar });
        const cameraReset = createToolButton({ icon: iconCameraReset, parent: toolbar });

        cameraFrame.addEventListener('click', () => events.fire('camera.focus'));
        cameraReset.addEventListener('click', () => events.fire('camera.reset'));

        tooltips.register(cameraFrame, tip('tooltip.right-toolbar.frame-selection', 'camera.focus'), 'right');
        tooltips.register(cameraReset, tip('tooltip.right-toolbar.reset-camera', 'camera.reset'), 'right');

        createSeparator(toolbar);

        // Color panel & View options toggles
        const colorPanelBtn = createToolButton({ icon: iconColorPanel, parent: toolbar });
        const optionsBtn = createToolButton({ icon: iconOptions, parent: toolbar });

        colorPanelBtn.addEventListener('click', () => events.fire('colorPanel.toggleVisible'));
        optionsBtn.addEventListener('click', () => events.fire('viewPanel.toggleVisible'));

        tooltips.register(colorPanelBtn, tip('tooltip.right-toolbar.colors'), 'right');
        tooltips.register(optionsBtn, tip('tooltip.right-toolbar.view-options'), 'right');

        // === Event Listeners ===

        // Tool activation
        const toolMap: Record<string, HTMLButtonElement> = {
            rectSelection: picker,
            lassoSelection: lasso,
            polygonSelection: polygon,
            brushSelection: brush,
            floodSelection: flood,
            eyedropperSelection: eyedropper,
            sphereSelection: sphere,
            boxSelection: box,
            distanceMeasurement: ruler
        };

        events.on('tool.activated', (toolName: string) => {
            Object.entries(toolMap).forEach(([name, btn]) => {
                btn.classList.toggle('active', name === toolName);
            });
        });

        // Camera mode (centers/rings)
        events.on('camera.mode', (mode: string) => {
            modeToggle.classList.toggle('active', mode === 'rings');
            modeToggle.innerHTML = mode === 'rings' ? iconSplatModeOn : iconSplatModeOff;
        });

        // Camera overlay
        events.on('camera.overlay', (value: boolean) => {
            showHide.classList.toggle('active', value);
        });

        // Camera control mode (no UI buttons, but still listen for state)

        // Panel visibility
        events.on('colorPanel.visible', (visible: boolean) => {
            colorPanelBtn.classList.toggle('active', visible);
        });

        events.on('viewPanel.visible', (visible: boolean) => {
            optionsBtn.classList.toggle('active', visible);
        });
    }
}

export { LeftToolbar };
