/**
 * Progress (New)
 * Pure HTML/CSS replacement for PCUI Progress.
 */

import { localize } from '../ui/localization';
import { createContainer, createElement, createLabel, createButton } from './dom-helpers';

class NewProgress {
    dom: HTMLDivElement;
    onCancel: (() => void) | null = null;
    private _hidden = true;
    private _header: HTMLSpanElement;
    private _text: HTMLDivElement;
    private _bar: HTMLDivElement;
    private _cancelBtn: HTMLButtonElement;

    constructor() {
        this.dom = createContainer({
            id: 'progress-container',
            class: 'ax-modal-overlay',
            style: { display: 'none' }
        });
        this.dom.tabIndex = 0;

        const dialog = createContainer({
            class: 'ax-modal',
            parent: this.dom,
            style: { minWidth: '320px', maxWidth: '400px' }
        });

        // Header
        const headerEl = createContainer({ class: 'ax-modal__header', parent: dialog });
        this._header = createLabel({ parent: headerEl });

        // Body
        const bodyEl = createContainer({ class: 'ax-modal__body', parent: dialog });
        this._text = createContainer({
            parent: bodyEl,
            style: { fontSize: 'var(--ax-font-size-sm)', color: 'var(--ax-text-secondary)', minHeight: '20px' }
        });

        // Progress bar
        const barContainer = createContainer({ class: 'ax-progress', parent: bodyEl, style: { marginTop: '8px' } });
        this._bar = createContainer({ class: 'ax-progress__bar', parent: barContainer });
        this._bar.style.width = '0%';

        // Cancel button
        const footer = createContainer({ class: 'ax-modal__footer', parent: dialog });
        this._cancelBtn = createButton({
            text: localize('panel.render.cancel'),
            parent: footer,
            style: { display: 'none' }
        });
        this._cancelBtn.addEventListener('click', () => {
            if (this.onCancel) this.onCancel();
        });

        this.dom.addEventListener('keydown', (event) => {
            if (this._hidden) return;
            event.stopPropagation();
            event.preventDefault();
        });
    }

    setHeader(headerText: string) {
        this._header.textContent = headerText;
    }

    setText(text: string) {
        this._text.textContent = text;
    }

    setProgress(progress: number) {
        this._bar.style.width = `${progress}%`;
        this._bar.style.backgroundColor = 'var(--ax-accent)';
    }

    showCancelButton(show: boolean) {
        this._cancelBtn.style.display = show ? '' : 'none';
    }

    get hidden() { return this._hidden; }
    set hidden(v: boolean) {
        this._hidden = v;
        this.dom.style.display = v ? 'none' : '';
    }
}

export { NewProgress };
