// enhanced-spinner.ts - 디버깅 로그 추가
import { Container, Element, Label } from '@playcanvas/pcui';
import { Events } from '../events';

/**
 * 진행 상태 표시 기능이 강화된 스피너 컴포넌트
 * 기존 Spinner와 독립적으로 사용 가능
 */
class EnhancedSpinner extends Container {
    statusElement: Label;
    progressTrack: Element;
    progressBar: Element;
    isDownloading: boolean = false;
    
    constructor(events: Events, args = {}) {
        console.log('[EnhancedSpinner] 생성자 호출');
        args = {
            ...args,
            id: 'enhanced-spinner-container',
            hidden: true
        };
        
        super(args);

        if (this.dom) {
            this.dom.style.display = 'none';
        }
        
        this.dom.tabIndex = 0;
        
        try {
            console.log('[EnhancedSpinner] UI 요소 생성 시작');
            
            // 중앙 컨테이너 생성
            const centerContainer = new Container({
                class: 'enhanced-spinner-center-container'
            });
            this.append(centerContainer);
            console.log('[EnhancedSpinner] 중앙 컨테이너 생성 완료');
            
            // 스피너 요소 추가
            const spinner = new Element({
                dom: 'div',
                class: 'enhanced-spinner-animation'
            });
            centerContainer.append(spinner);
            console.log('[EnhancedSpinner] 스피너 애니메이션 요소 생성 완료');
            
            // 상태 레이블 추가
            this.statusElement = new Label({
                class: 'enhanced-spinner-status',
                text: '로딩 중...'
            });
            centerContainer.append(this.statusElement);
            console.log('[EnhancedSpinner] 상태 레이블 생성 완료');
            
            // 프로그레스 트랙 (배경) 생성
            this.progressTrack = new Element({
                dom: 'div',
                class: 'enhanced-spinner-progress-track'
            });
            centerContainer.append(this.progressTrack);
            console.log('[EnhancedSpinner] 프로그레스 트랙 생성 완료');
            
            // 프로그레스 바 생성
            this.progressBar = new Element({
                dom: 'div',
                class: 'enhanced-spinner-progress-bar'
            });
            
            // DOM으로 직접 추가 (PCUI 계층 구조 우회)
            this.progressTrack.dom.appendChild(this.progressBar.dom);
            console.log('[EnhancedSpinner] 프로그레스 바 생성 및 추가 완료');
            
            // 키보드 이벤트 중단
            this.dom.addEventListener('keydown', (event) => {
                if (this.hidden) return;
                event.stopPropagation();
                event.preventDefault();
            });
            console.log('[EnhancedSpinner] 키보드 이벤트 핸들러 등록 완료');
            
            // 이벤트 핸들러 등록
            this.registerEvents(events);
            console.log('[EnhancedSpinner] 생성자 완료');
        } catch (error) {
            console.error('[EnhancedSpinner] 생성 중 오류 발생:', error);
            throw error;
        }
    }
    
    // 진행률 설정 (0-1 사이 값)
    setProgress(progress: number) {
        if (progress < 0) progress = 0;
        if (progress > 1) progress = 1;
        
        const percent = Math.round(progress * 100);
        console.log(`[EnhancedSpinner] 진행률 설정: ${percent}%`);
        this.progressBar.dom.style.width = `${percent}%`;
    }
    
    registerEvents(events: Events) {
        console.log('[EnhancedSpinner] 이벤트 등록 시작');
        
        // 다운로드 시작 이벤트
        events.on('s3.downloadStart', (filename: string) => {
            console.log('[EnhancedSpinner] 다운로드 시작 이벤트 수신:', filename);
            this.hidden = false;
            this.isDownloading = true;
            this.statusElement.text = `파일 다운로드 중: ${filename}`;
            this.progressTrack.hidden = false;
            this.setProgress(0);
        });
        
        // 다운로드 진행 이벤트
        events.on('s3.downloadProgress', (progress: number) => {
            console.log(`[EnhancedSpinner] 다운로드 진행 이벤트 수신: ${Math.round(progress * 100)}%`);
            if (this.isDownloading) {
                this.setProgress(progress);
                this.statusElement.text = `다운로드 중... ${Math.round(progress * 100)}%`;
            }
        });
        
        // 다운로드 완료 이벤트
        events.on('s3.downloadComplete', () => {
            console.log('[EnhancedSpinner] 다운로드 완료 이벤트 수신');
            this.statusElement.text = '다운로드 완료, 모델 처리 중...';
            this.setProgress(1);
        });
        
        // 모델 처리 단계 이벤트
        events.on('s3.modelProcessing', (message: string) => {
            console.log('[EnhancedSpinner] 모델 처리 이벤트 수신:', message);
            this.statusElement.text = message || '모델 처리 중...';
        });
        
        // 모든 처리 완료 이벤트
        events.on('s3.processingComplete', () => {
            console.log('[EnhancedSpinner] 처리 완료 이벤트 수신');
            this.statusElement.text = '로드 완료';
            this.setProgress(1);
            
            // 스피너 닫기 전 지연시간
            setTimeout(() => {
                console.log('[EnhancedSpinner] 처리 완료 후 스피너 숨김 처리');
                this.hidden = true;
                this.resetState();
            }, 500);
        });
        
        // 오류 발생 이벤트
        events.on('s3.error', (errorMessage: string) => {
            console.log('[EnhancedSpinner] 오류 이벤트 수신:', errorMessage);
            this.statusElement.text = `오류: ${errorMessage}`;
            this.progressTrack.hidden = true;
            
            // 3초 후 숨김 처리
            setTimeout(() => {
                console.log('[EnhancedSpinner] 오류 후 스피너 숨김 처리');
                this.hidden = true;
                this.resetState();
            }, 3000);
        });
        
        // 스피너 시작 이벤트
        events.on('startSpinner', () => {
            console.log('[EnhancedSpinner] 스피너 시작 이벤트 수신');
            // 기본 스피너만 반응하도록 여기서는 아무 동작 안함
        });
        
        // 스피너 종료 이벤트
        events.on('stopSpinner', () => {
            console.log('[EnhancedSpinner] 스피너 종료 이벤트 수신');
            // 안전하게 스피너를 숨기도록 추가
            setTimeout(() => {
                console.log('[EnhancedSpinner] stopSpinner 이벤트에 의한 스피너 숨김 처리');
                this.hidden = true;
                this.resetState();
            }, 100);
        });
        
        console.log('[EnhancedSpinner] 이벤트 등록 완료');
    }
    
    resetState() {
        console.log('[EnhancedSpinner] 상태 초기화');
        this.isDownloading = false;
        this.statusElement.text = '로딩 중...';
        this.progressTrack.hidden = true;
        this.setProgress(0);
    }
    
    // 수동으로 스피너 표시
    show(message?: string) {
        console.log('[EnhancedSpinner] 스피너 표시 요청:', message);
        if (message) {
            this.statusElement.text = message;
        }
        this.hidden = false;
    }
    
    // 수동으로 스피너 숨김
    hide() {
        console.log('[EnhancedSpinner] 스피너 숨김 요청');
        this.hidden = true;
        this.resetState();
    }
    
    // hidden 상태가 변경될 때마다 로그 출력
    set hidden(value: boolean) {
        console.log(`[EnhancedSpinner] hidden 상태 변경: ${value}`);
        super.hidden = value;
        
        // 항상 DOM 레벨에서도 직접 숨김 처리
        if (this.dom) {
            this.dom.style.display = value ? 'none' : 'flex';
        }
    }
    
    get hidden(): boolean {
        return super.hidden;
    }
}

export { EnhancedSpinner };