/**
 * MenuBar
 * Desktop-style menu bar replacing PCUI-based Menu + MenuPanel.
 * Pure HTML/CSS implementation with the same event wiring.
 */

import { Events } from '../events';
import { recentFiles } from '../recent-files';
import { ShortcutManager } from '../shortcut-manager';
import { localize } from '../ui/localization';
import { createElement, createContainer, createLabel } from './dom-helpers';

// SVG imports (reuse existing)
import sceneNew from '../ui/svg/new.svg';
import sceneOpen from '../ui/svg/open.svg';
import sceneImport from '../ui/svg/import.svg';
import sceneExport from '../ui/svg/export.svg';
import sceneSave from '../ui/svg/save.svg';
import selectAll from '../ui/svg/select-all.svg';
import selectNone from '../ui/svg/select-none.svg';
import selectInverse from '../ui/svg/select-inverse.svg';
import selectLock from '../ui/svg/select-lock.svg';
import selectUnlock from '../ui/svg/select-unlock.svg';
import selectDelete from '../ui/svg/delete.svg';
import selectDuplicate from '../ui/svg/select-duplicate.svg';
import selectSeparate from '../ui/svg/select-separate.svg';

interface MenuItem {
    text?: string;
    icon?: string;    // SVG data URI
    shortcut?: string;
    separator?: boolean;
    disabled?: boolean;
    isEnabled?: () => boolean | Promise<boolean>;
    isVisible?: () => boolean | Promise<boolean>;
    onSelect?: () => void;
    children?: MenuItem[];
}

const decodeSvg = (svgDataUri: string): string => {
    if (!svgDataUri) return '';
    try {
        const decoded = decodeURIComponent(svgDataUri.substring('data:image/svg+xml,'.length));
        return decoded;
    } catch {
        return '';
    }
};

class MenuBar {
    dom: HTMLDivElement;
    private _openMenu: HTMLDivElement | null = null;
    private _openMenuOption: HTMLDivElement | null = null;

    constructor(events: Events) {
        this.dom = createContainer({ id: 'menu-bar' });

        const menubarInner = createContainer({ class: 'ax-menubar', parent: this.dom });

        const shortcutManager: ShortcutManager = events.invoke('shortcutManager');

        // Build menu definitions
        const fileMenu = this._buildFileMenu(events, shortcutManager);
        const selectMenu = this._buildSelectMenu(events, shortcutManager);
        const renderMenu = this._buildRenderMenu(events);
        const helpMenu = this._buildHelpMenu(events);

        // Create menu items
        const menuDefs: { label: string; items: MenuItem[]; skipFlutter?: boolean }[] = [
            { label: localize('menu.file'), items: fileMenu },
            { label: localize('menu.select'), items: selectMenu },
            { label: localize('menu.render'), items: renderMenu, skipFlutter: true },
            { label: localize('menu.help'), items: helpMenu }
        ];

        menuDefs.forEach(def => {
            if (def.skipFlutter && window.isFlutterApp) return;

            const option = createContainer({
                class: 'ax-menubar__item',
                text: def.label,
                parent: menubarInner
            });

            option.addEventListener('pointerdown', (e) => {
                e.stopPropagation();
                if (this._openMenuOption === option) {
                    this._closeAllMenus();
                } else {
                    this._openDropdown(option, def.items);
                }
            });

            option.addEventListener('pointerenter', () => {
                if (this._openMenu && this._openMenuOption !== option) {
                    this._openDropdown(option, def.items);
                }
            });
        });

        // Close on outside click
        window.addEventListener('pointerdown', (e) => {
            if (this._openMenu) {
                const target = e.target as Node;
                // Don't close if clicking inside the menu bar or any open dropdown
                if (this.dom.contains(target)) return;
                const dropdowns = document.querySelectorAll('.ax-dropdown');
                for (const dd of dropdowns) {
                    if (dd.contains(target)) return;
                }
                this._closeAllMenus();
            }
        }, true);
    }

    private _openDropdown(option: HTMLDivElement, items: MenuItem[]) {
        this._closeAllMenus();

        const rect = option.getBoundingClientRect();
        const dropdown = this._createDropdown(items);
        dropdown.style.position = 'fixed';
        dropdown.style.left = `${rect.left}px`;
        dropdown.style.top = `${rect.bottom}px`;

        document.body.appendChild(dropdown);
        option.classList.add('open');

        this._openMenu = dropdown;
        this._openMenuOption = option;

        // Update enabled states
        this._updateMenuStates(dropdown, items);
    }

    private _closeAllMenus() {
        if (this._openMenu) {
            this._openMenu.remove();
            this._openMenu = null;
        }
        if (this._openMenuOption) {
            this._openMenuOption.classList.remove('open');
            this._openMenuOption = null;
        }
        // Remove any sub-menus
        document.querySelectorAll('.ax-dropdown').forEach(el => el.remove());
    }

    private _createDropdown(items: MenuItem[]): HTMLDivElement {
        const dropdown = createContainer({ class: 'ax-dropdown' });

        items.forEach((item, index) => {
            if (item.separator) {
                createElement('div', { class: 'ax-dropdown__separator', parent: dropdown });
                return;
            }

            if (!item.text) {
                // Empty object = separator
                createElement('div', { class: 'ax-dropdown__separator', parent: dropdown });
                return;
            }

            // Skip invisible items
            if (item.isVisible) {
                const visible = item.isVisible();
                if (visible === false) return;
            }

            const itemEl = createContainer({
                class: 'ax-dropdown__item',
                parent: dropdown
            });

            itemEl.setAttribute('data-index', String(index));

            // Icon
            if (item.icon) {
                const iconHtml = decodeSvg(item.icon);
                if (iconHtml) {
                    const iconEl = createElement('span', {
                        class: 'ax-dropdown__item__icon',
                        style: { width: '16px', height: '16px', flexShrink: '0', display: 'flex', alignItems: 'center' }
                    });
                    iconEl.innerHTML = iconHtml;
                    const svg = iconEl.querySelector('svg');
                    if (svg) {
                        svg.style.width = '16px';
                        svg.style.height = '16px';
                        svg.style.fill = 'currentColor';
                    }
                    itemEl.insertBefore(iconEl, itemEl.firstChild);
                }
            }

            // Text
            createLabel({
                text: item.text,
                style: { flex: '1' },
                parent: itemEl
            });

            // Shortcut
            if (item.shortcut) {
                createLabel({
                    text: item.shortcut,
                    class: 'ax-dropdown__item__shortcut',
                    parent: itemEl
                });
            }

            // Submenu arrow
            if (item.children && item.children.length > 0) {
                createLabel({
                    text: '\u25B6',
                    class: 'ax-dropdown__item__arrow',
                    style: { fontSize: '8px', marginLeft: 'auto' },
                    parent: itemEl
                });

                let subDropdown: HTMLDivElement | null = null;
                let subTimer = -1;

                itemEl.addEventListener('pointerenter', () => {
                    clearTimeout(subTimer);
                    subTimer = window.setTimeout(() => {
                        if (subDropdown) subDropdown.remove();

                        subDropdown = this._createDropdown(item.children!);
                        const itemRect = itemEl.getBoundingClientRect();
                        subDropdown.style.position = 'fixed';
                        subDropdown.style.left = `${itemRect.right + 2}px`;
                        subDropdown.style.top = `${itemRect.top}px`;

                        document.body.appendChild(subDropdown);
                        this._updateMenuStates(subDropdown, item.children!);
                    }, 150);
                });

                itemEl.addEventListener('pointerleave', (e) => {
                    clearTimeout(subTimer);
                    // Don't close if entering the submenu
                    const related = e.relatedTarget as Node;
                    if (subDropdown && subDropdown.contains(related)) return;

                    subTimer = window.setTimeout(() => {
                        if (subDropdown) {
                            subDropdown.remove();
                            subDropdown = null;
                        }
                    }, 300);
                });
            } else if (item.onSelect) {
                // Click handler
                itemEl.addEventListener('click', (e) => {
                    e.stopPropagation();
                    if (!itemEl.classList.contains('disabled')) {
                        this._closeAllMenus();
                        item.onSelect!();
                    }
                });
            }

            // Disabled state
            if (item.disabled) {
                itemEl.classList.add('disabled');
            }
        });

        // Stop propagation on the dropdown itself
        dropdown.addEventListener('pointerdown', (e) => e.stopPropagation());

        return dropdown;
    }

    private async _updateMenuStates(dropdown: HTMLDivElement, items: MenuItem[]) {
        const itemEls = dropdown.querySelectorAll('.ax-dropdown__item');
        let dataIndex = 0;
        for (const itemEl of itemEls) {
            const idx = parseInt(itemEl.getAttribute('data-index') || String(dataIndex));
            const item = items[idx];
            if (item && item.isEnabled) {
                const enabled = await item.isEnabled();
                if (!enabled) {
                    itemEl.classList.add('disabled');
                } else {
                    itemEl.classList.remove('disabled');
                }
            }
            dataIndex++;
        }
    }

    // ========== Menu Definitions ==========

    private _buildFileMenu(events: Events, shortcutManager: ShortcutManager): MenuItem[] {
        const items: MenuItem[] = [
            {
                text: localize('menu.file.new'),
                icon: sceneNew,
                isEnabled: () => !events.invoke('scene.empty'),
                onSelect: () => events.invoke('doc.new')
            }
        ];

        if (!window.isFlutterApp) {
            items.push({
                text: localize('menu.file.open'),
                icon: sceneOpen,
                onSelect: async () => await events.invoke('doc.open')
            });

            items.push({
                text: localize('menu.file.open-recent'),
                icon: sceneOpen,
                children: [], // Will be populated dynamically
                isEnabled: async () => {
                    // This will be checked when menu opens
                    return true;
                }
            });
        }

        items.push({ separator: true });

        if (!window.isFlutterApp) {
            items.push({
                text: localize('menu.file.save'),
                icon: sceneSave,
                isEnabled: () => events.invoke('doc.name'),
                onSelect: async () => await events.invoke('doc.save')
            });
            items.push({
                text: localize('menu.file.save-as', { ellipsis: true }),
                icon: sceneSave,
                isEnabled: () => !events.invoke('scene.empty'),
                onSelect: async () => await events.invoke('doc.saveAs')
            });
            items.push({ separator: true });
        }

        items.push({
            text: localize('menu.file.import', { ellipsis: true }),
            icon: sceneImport,
            onSelect: async () => await events.invoke('scene.import')
        });

        if (!window.isFlutterApp) {
            items.push({
                text: localize('menu.file.view-samples'),
                onSelect: async () => await events.invoke('loadSamplePly')
            });
        }

        items.push({
            text: localize('menu.file.colmap-camera'),
            children: [
                {
                    text: localize('menu.file.load-camera-data'),
                    icon: sceneImport,
                    onSelect: () => events.invoke('scene.importColmap')
                },
                {
                    text: localize('menu.file.toggle-camera'),
                    shortcut: 'K',
                    onSelect: () => events.fire('colmapCamera.toggle')
                }
            ]
        });

        // Export submenu
        const exportChildren: MenuItem[] = [
            {
                text: localize('menu.file.export.ply'),
                icon: sceneExport,
                isEnabled: () => !events.invoke('scene.empty'),
                onSelect: () => events.invoke('scene.export', 'ply')
            }
        ];

        if (!window.isFlutterApp) {
            exportChildren.push({
                text: localize('menu.file.export.splat'),
                icon: sceneExport,
                isEnabled: () => !events.invoke('scene.empty'),
                onSelect: () => events.invoke('scene.export', 'splat')
            });
            exportChildren.push({
                text: localize('menu.file.export.sog'),
                icon: sceneExport,
                isEnabled: () => !events.invoke('scene.empty'),
                onSelect: () => events.invoke('scene.export', 'sog')
            });
            exportChildren.push({ separator: true });
            exportChildren.push({
                text: localize('menu.file.export.viewer', { ellipsis: true }),
                icon: sceneExport,
                isEnabled: () => !events.invoke('scene.empty'),
                onSelect: () => events.invoke('scene.export', 'viewer')
            });
        }

        items.push({
            text: localize('menu.file.export'),
            icon: sceneExport,
            children: exportChildren
        });

        if (!window.isFlutterApp) {
            items.push({ separator: true });
            items.push({
                text: localize('menu.file.manage-ply'),
                onSelect: () => events.fire('cacheManager.toggle')
            });
        }

        return items;
    }

    private _buildSelectMenu(events: Events, shortcutManager: ShortcutManager): MenuItem[] {
        return [
            {
                text: localize('menu.select.all'),
                icon: selectAll,
                shortcut: shortcutManager.formatShortcut('select.all'),
                onSelect: () => events.fire('select.all')
            },
            {
                text: localize('menu.select.none'),
                icon: selectNone,
                shortcut: shortcutManager.formatShortcut('select.none'),
                onSelect: () => events.fire('select.none')
            },
            {
                text: localize('menu.select.invert'),
                icon: selectInverse,
                shortcut: shortcutManager.formatShortcut('select.invert'),
                onSelect: () => events.fire('select.invert')
            },
            { separator: true },
            {
                text: localize('menu.select.lock'),
                icon: selectLock,
                shortcut: shortcutManager.formatShortcut('select.hide'),
                isEnabled: () => events.invoke('selection.splats'),
                onSelect: () => events.fire('select.hide')
            },
            {
                text: localize('menu.select.unlock'),
                icon: selectUnlock,
                shortcut: shortcutManager.formatShortcut('select.unhide'),
                onSelect: () => events.fire('select.unhide')
            },
            {
                text: localize('menu.select.delete'),
                icon: selectDelete,
                shortcut: shortcutManager.formatShortcut('select.delete'),
                isEnabled: () => events.invoke('selection.splats'),
                onSelect: () => events.fire('select.delete')
            },
            {
                text: localize('menu.select.reset'),
                onSelect: () => events.fire('scene.reset')
            },
            { separator: true },
            {
                text: localize('menu.select.duplicate'),
                icon: selectDuplicate,
                isEnabled: () => events.invoke('selection.splats'),
                onSelect: () => events.fire('select.duplicate')
            },
            {
                text: localize('menu.select.separate'),
                icon: selectSeparate,
                isEnabled: () => events.invoke('selection.splats'),
                onSelect: () => events.fire('select.separate')
            }
        ];
    }

    private _buildRenderMenu(events: Events): MenuItem[] {
        return [
            {
                text: localize('menu.render.image', { ellipsis: true }),
                icon: sceneExport,
                onSelect: async () => await events.invoke('show.imageSettingsDialog')
            },
            {
                text: localize('menu.render.video', { ellipsis: true }),
                icon: sceneExport,
                onSelect: async () => await events.invoke('show.videoSettingsDialog')
            }
        ];
    }

    private _buildHelpMenu(events: Events): MenuItem[] {
        return [
            {
                text: localize('menu.help.video-tutorials'),
                children: [
                    {
                        text: localize('menu.help.video-tutorials.basics'),
                        onSelect: () => window.open('https://youtu.be/MwzaEM2I55I', '_blank')?.focus()
                    },
                    {
                        text: localize('menu.help.video-tutorials.in-depth'),
                        onSelect: () => window.open('https://youtu.be/J37rTieKgJ8', '_blank')?.focus()
                    }
                ]
            },
            {
                text: localize('menu.help.user-guide'),
                onSelect: () => window.open('https://developer.playcanvas.com/user-manual/gaussian-splatting/editing/supersplat/', '_blank')?.focus()
            },
            {
                text: localize('menu.help.shortcuts'),
                onSelect: () => events.fire('show.shortcuts')
            },
            { separator: true },
            {
                text: localize('menu.help.discord'),
                onSelect: () => window.open('https://discord.gg/T3pnhRTTAY', '_blank')?.focus()
            },
            {
                text: localize('menu.help.forum'),
                onSelect: () => window.open('https://forum.playcanvas.com', '_blank')?.focus()
            },
            { separator: true },
            {
                text: localize('menu.help.github-repo'),
                onSelect: () => window.open('https://github.com/playcanvas/supersplat', '_blank')?.focus()
            },
            {
                text: localize('menu.help.log-issue'),
                onSelect: () => window.open('https://github.com/playcanvas/supersplat/issues', '_blank')?.focus()
            },
            { separator: true },
            {
                text: localize('menu.help.about'),
                onSelect: () => events.fire('show.about')
            }
        ];
    }
}

export { MenuBar };
