import {
    BoundingBox,
    Color,
    Entity,
    Quat,
    Vec3,
    StandardMaterial,
    BLEND_NORMAL
} from 'playcanvas';

import { Element, ElementType } from './element';
import { Events } from './events';
import { Serializer } from './serializer';

// Define a new element type for colmap cameras
enum CustomElementType {
    colmapCamera = 'colmapCamera'
}

// Add the new element type to the ElementType enum
Object.assign(ElementType, CustomElementType);

// COLMAP 카메라 클래스 - 기본 도형 사용
class ColmapCamera extends Element {
    entity: Entity;
    id: string;
    imageId: number;
    imageName: string;
    position: Vec3;
    rotation: Quat;
    focalLength: number;
    selected: boolean = false;
    bodyMaterial: StandardMaterial;
    lensMaterial: StandardMaterial;
    bodyEntity: Entity;
    lensEntity: Entity;
    viewfinderEntity: Entity;

    constructor(
        id: string,
        imageId: number,
        imageName: string,
        position: Vec3,
        rotation: Quat,
        focalLength: number = 1.0
    ) {
        super(CustomElementType.colmapCamera);

        this.id = id;
        this.imageId = imageId;
        this.imageName = imageName;
        this.position = position;
        this.rotation = rotation;
        this.focalLength = focalLength;
    }

    add() {
        if (!this.scene) {
            console.error("Cannot add ColmapCamera, scene is null");
            return;
        }

        // 메인 카메라 엔티티 생성
        this.entity = new Entity(`ColmapCamera_${this.id}`);
        // 중요: 엔티티를 contentRoot에 추가하기 전에 씬의 elements 배열에 명시적으로 추가
        // 이 부분이 매우 중요합니다!
        if (!this.scene.elements.includes(this)) {
            this.scene.elements.push(this);
        }
        this.scene.contentRoot.addChild(this.entity);

        // 위치 및 회전 설정
        this.entity.setLocalPosition(this.position);
        this.entity.setLocalRotation(this.rotation);

        // 카메라 모델 생성
        this.createCameraModel();

        // 마우스 오버 시 하이라이트 효과
        this.scene.events.on('camera.frustumPicked', (details) => {
            if (details.entity === this.entity ||
                details.entity === this.bodyEntity ||
                details.entity === this.lensEntity ||
                details.entity === this.viewfinderEntity) {
                this.selected = true;
                this.highlightModel(true);
            } else if (this.selected) {
                this.selected = false;
                this.highlightModel(false);
            }
        });
    }

    createCameraModel() {
        // 메인 카메라 도형 컨테이너
        const modelContainer = new Entity('CameraModel');
        this.entity.addChild(modelContainer);

        // 카메라 본체 (박스) 생성
        this.bodyEntity = new Entity('CameraBody');
        modelContainer.addChild(this.bodyEntity);
        this.bodyEntity.addComponent('render', {
            type: 'box',
            castShadows: false,
            // 깊이 테스트 활성화
            depthTest: true
        });

        // 카메라 본체 위치 및 크기 설정
        this.bodyEntity.setLocalScale(0.45, 0.32, 0.25);
        this.bodyEntity.setLocalPosition(0, 0, 0);

        // 카메라 렌즈 (원통) 생성
        this.lensEntity = new Entity('CameraLens');
        modelContainer.addChild(this.lensEntity);
        this.lensEntity.addComponent('render', {
            type: 'cylinder',
            castShadows: false,
            // 깊이 테스트 활성화
            depthTest: true
        });

        // 렌즈 위치 및 크기 설정
        this.lensEntity.setLocalScale(0.12, 0.18, 0.12);
        this.lensEntity.setLocalPosition(0, 0, -0.2);
        this.lensEntity.setLocalEulerAngles(90, 0, 0);

        // 카메라 뷰파인더 (작은 박스) 생성
        this.viewfinderEntity = new Entity('CameraViewfinder');
        modelContainer.addChild(this.viewfinderEntity);
        this.viewfinderEntity.addComponent('render', {
            type: 'box',
            castShadows: false,
            // 깊이 테스트 활성화
            depthTest: true
        });

        // 뷰파인더 위치 및 크기 설정
        this.viewfinderEntity.setLocalScale(0.18, 0.12, 0.18);
        this.viewfinderEntity.setLocalPosition(0, 0.18, 0);

        // 본체 재질 생성
        this.bodyMaterial = new StandardMaterial();
        this.bodyMaterial.diffuse = new Color(1.5, 1.5, 1.5);
        this.bodyMaterial.specular = new Color(1, 1, 1);
        this.bodyMaterial.emissive = new Color(1, 1, 1);
        this.bodyMaterial.emissiveIntensity = 1.2;
        this.bodyMaterial.shininess = 100;
        this.bodyMaterial.opacity = 0.7;
        this.bodyMaterial.blendType = BLEND_NORMAL;
        // 깊이 쓰기 활성화 (투명해도 깊이 정보 기록)
        this.bodyMaterial.depthWrite = true;
        this.bodyMaterial.update();

        // 렌즈 재질 생성
        this.lensMaterial = new StandardMaterial();
        this.lensMaterial.diffuse = new Color(1.0, 1.0, 1.3);
        this.lensMaterial.specular = new Color(1, 1, 1);
        this.lensMaterial.emissive = new Color(0.9, 0.9, 1.0);
        this.lensMaterial.emissiveIntensity = 1.0;
        this.lensMaterial.shininess = 95;
        this.lensMaterial.opacity = 0.7;
        this.lensMaterial.blendType = BLEND_NORMAL;
        // 깊이 쓰기 활성화
        this.lensMaterial.depthWrite = true;
        this.lensMaterial.update();

        // 재질 적용
        if (this.bodyEntity.render && this.bodyEntity.render.meshInstances) {
            this.bodyEntity.render.meshInstances[0].material = this.bodyMaterial;
        }

        if (this.lensEntity.render && this.lensEntity.render.meshInstances) {
            this.lensEntity.render.meshInstances[0].material = this.lensMaterial;
        }

        if (this.viewfinderEntity.render && this.viewfinderEntity.render.meshInstances) {
            this.viewfinderEntity.render.meshInstances[0].material = this.bodyMaterial;
        }

        // 모델 전체를 적절한 크기로 조정
        modelContainer.setLocalScale(0.7, 0.7, 0.7);

        // 모델이 z축 방향을 향하도록 설정
        modelContainer.setLocalEulerAngles(0, 180, 0);
    }

    // 모델 하이라이트 효과
    highlightModel(highlight: boolean) {
        // 하이라이트 상태가 이미 동일하면 리턴
        if (this.selected === highlight) {
            return;
        }

        this.selected = highlight;

        try {
            const color = highlight ? new Color(1, 1, 0) : new Color(1, 1, 1); // 노란색 또는 원래 색상
            const intensity = highlight ? 1.5 : 1.0; // 하이라이트 시 더 강한 발광
            const opacity = highlight ? 0.8 : 0.5; // 하이라이트 시 더 불투명하게

            if (this.bodyMaterial) {
                this.bodyMaterial.emissive = color;
                this.bodyMaterial.emissiveIntensity = intensity;
                this.bodyMaterial.opacity = opacity;
                this.bodyMaterial.update();
            }

            if (this.lensMaterial) {
                // 렌즈는 약간 다른 색조로 강조
                const lensColor = highlight ? new Color(0.8, 0.8, 0) : new Color(0.9, 0.9, 0.9);
                this.lensMaterial.emissive = lensColor;
                this.lensMaterial.emissiveIntensity = intensity;
                this.lensMaterial.opacity = opacity;
                this.lensMaterial.update();
            }

            // 크기 변경 - 하이라이트 시 더 크게
            if (this.entity && this.entity.children.length > 0) {
                const modelContainer = this.entity.children[0];
                if (modelContainer) {
                    const scale = highlight ? 0.9 : 0.7; // 하이라이트 시 약간 더 크게
                    modelContainer.setLocalScale(scale, scale, scale);
                }
            }
        } catch (error) {
            console.error(`하이라이트 에러:`, error);
        }
    }

    onUpdate(deltaTime: number) {
        // 기본 체크
        if (!this.scene || !this.scene.camera || !this.entity ||
            !this.bodyMaterial || !this.lensMaterial) {
            return;
        }

        try {
            // 메인 카메라 정보
            const mainCamera = this.scene.camera.entity;
            const mainCameraPos = mainCamera.getPosition();

            // 카메라 모델 정보
            const cameraPos = this.entity.getPosition();

            // 메인 카메라 방향과 카메라 모델 방향의 내적 계산
            const cameraDir = this.entity.forward;
            const viewDir = new Vec3();
            viewDir.sub2(mainCameraPos, cameraPos).normalize();

            // 내적 값은 -1(완전히 반대 방향)에서 1(완전히 같은 방향)
            // 여기서는 카메라의 뒷면을 보고 있는지 체크하기 위해 사용
            const dot = cameraDir.dot(viewDir);

            // 기준값
            const hideThreshold = -0.3;  // 이 값보다 작으면 완전히 숨김
            const fullVisibleThreshold = 0.3;  // 이 값보다 크면 완전히 보임

            if (dot < hideThreshold) {
                // 완전히 숨김
                if (this.entity.enabled) {
                    this.entity.enabled = false;
                }
            } else {
                // 다시 활성화
                if (!this.entity.enabled) {
                    this.entity.enabled = true;
                }

                // 점진적 투명도 계산
                let opacity;
                if (dot >= fullVisibleThreshold) {
                    opacity = 0.8;  // 최대 불투명도
                } else {
                    // hideThreshold에서 fullVisibleThreshold까지 선형 보간
                    const t = (dot - hideThreshold) / (fullVisibleThreshold - hideThreshold);
                    opacity = 0.1 + t * 0.7;  // 0.1에서 0.8 사이로 보간
                }

                // 투명도 적용
                this.bodyMaterial.opacity = opacity;
                this.bodyMaterial.update();
                this.lensMaterial.opacity = opacity;
                this.lensMaterial.update();
            }
        } catch (error) {
            console.error("카메라 투명도 업데이트 중 오류:", error);
        }
    }

    remove() {
        if (this.entity) {
            this.entity.destroy();
            this.entity = null;
            this.bodyEntity = null;
            this.lensEntity = null;
            this.viewfinderEntity = null;
        }
    }

    serialize(serializer: Serializer) {
        try {
            // null 체크 추가
            if (!this.entity || !this.entity.getWorldTransform) {
                console.error("Entity is missing or incomplete");
                serializer.pack(this.id || "unknown", 0, "unknown", false);
                serializer.pack(0, 0, 0);
                serializer.pack(0, 0, 0, 1);
                serializer.pack(1.0);
                return;
            }

            serializer.packa(this.entity.getWorldTransform().data);
            serializer.pack(this.id, this.imageId, this.imageName, this.selected);
            serializer.pack(this.position.x, this.position.y, this.position.z);
            serializer.pack(this.rotation.x, this.rotation.y, this.rotation.z, this.rotation.w);
            serializer.pack(this.focalLength);
        } catch (error) {
            console.error("ColmapCamera 직렬화 중 오류:", error);
            // 기본값으로 직렬화
            serializer.pack(this.id || "unknown", 0, "unknown", false);
            serializer.pack(0, 0, 0);
            serializer.pack(0, 0, 0, 1);
            serializer.pack(1.0);
        }
    }

    get worldBound() {
        const bound = new BoundingBox();
        bound.setFromTransformedAabb(
            new BoundingBox(new Vec3(-0.25, -0.25, -0.25), new Vec3(0.25, 0.25, 0.25)),
            this.entity.getWorldTransform()
        );
        return bound;
    }
}

// COLMAP 카메라 이벤트 등록
const registerColmapCameraEvents = (events: Events) => {

    // 카메라 컬렉션 - 전역적으로 접근 가능하도록 명시적으로 선언
    const cameras: ColmapCamera[] = [];

    // 카메라 추가 이벤트
    events.on('colmapCamera.add', (cameraData: any) => {
        try {
            const {
                id,
                imageId,
                imageName,
                position,
                rotation,
                focalLength
            } = cameraData;

            const camera = new ColmapCamera(
                id,
                imageId || 0,
                imageName || id,
                position,
                rotation,
                focalLength || 1.0
            );

            cameras.push(camera);

            const scene = window.scene;
            camera.scene = scene;
            camera.add();

            events.fire('scene.addElement', camera);
        } catch (error) {
            console.error("카메라 생성 중 오류:", error);
        }
    });

    // 모든 카메라 가져오기 함수 개선
    events.function('colmapCamera.getAll', () => {
        return cameras;
    });

    // 모든 카메라 지우기 (새 기능 추가)
    events.function('colmapCamera.clear', () => {
        while (cameras.length > 0) {
            const camera = cameras.pop();
            if (camera && camera.entity) {
                camera.entity.destroy();
            }
        }
        return true;
    });

    // 현재 가시성 상태를 추적하는 변수
    let camerasVisible = true;

    // 토글 이벤트 핸들러 - 인자 없이 호출될 때 현재 상태 반전
    events.on('colmapCamera.toggle', () => {
        events.invoke('colmapCamera.toggleVisibility');
    });

    // 명시적 가시성 설정용 함수 - UI 버튼에서 호출
    events.function('colmapCamera.toggleVisibility', (visible?: boolean) => {
        // visible이 undefined면 현재 상태 반전
        if (visible === undefined) {
            camerasVisible = !camerasVisible;
        } else {
            camerasVisible = visible;
        }

        // 직접 엔티티 가시성 변경
        let enabledCount = 0;
        cameras.forEach(camera => {
            if (camera.entity) {
                camera.entity.enabled = camerasVisible;
                if (camerasVisible) enabledCount++;

                // 하위 엔티티들도 처리
                if (camera.bodyEntity) camera.bodyEntity.enabled = camerasVisible;
                if (camera.lensEntity) camera.lensEntity.enabled = camerasVisible;
                if (camera.viewfinderEntity) camera.viewfinderEntity.enabled = camerasVisible;
            }
        });

        // 씬 강제 재렌더링
        const scene = window.scene;
        if (scene) {
            scene.forceRender = true;
        }

        // UI 상태도 함께 업데이트
        events.fire('colmapCamera.visibilityChanged', camerasVisible);

        return camerasVisible;
    });

    // 카메라 클릭 이벤트 처리
    events.on('camera.frustumPicked', (details) => {
        const pickedCamera = cameras.find(cam =>
            cam.entity === details.entity ||
            cam.bodyEntity === details.entity ||
            cam.lensEntity === details.entity ||
            cam.viewfinderEntity === details.entity
        );

        if (pickedCamera) {
            console.log(`선택된 카메라: ${pickedCamera.imageName || pickedCamera.id}`);
        }
    });
};

export { ColmapCamera, registerColmapCameraEvents };