/**
 * FovPanel (New)
 * Pure HTML/CSS replacement for PCUI FovCustomPanel.
 * Shows in the right sidebar.
 */

import { Events } from '../events';
import { localize } from '../ui/localization';
import { createContainer, createElement, createPanel, createFormRow, blockPointerEvents } from './dom-helpers';
import { SelectInput } from './input-components';
import { TooltipSystem } from './tooltip-system';

const FOV_MAPPING: Record<string, Record<number, number>> = {
    'LF 오픈 게이트': { 24: 80.6, 35: 60.4, 50: 44.5, 85: 27.5, 100: 23.4, 135: 17.5 },
    'LF 2.39:1': { 24: 80.6, 35: 60.4, 50: 44.5, 85: 27.5, 100: 23.4, 135: 17.5 },
    'LF 16:9': { 24: 71.0, 35: 50.8, 50: 36.4, 85: 21.6, 100: 18.4, 135: 13.7 }
};

interface LetterboxSettings {
    enabled: boolean;
    aspectRatio: number;
}

class FovPanel {
    dom: HTMLDivElement;
    private _hidden: boolean;
    private events: Events;
    private modeSelect: SelectInput;
    private lensSelect: SelectInput;
    private currentLetterbox: LetterboxSettings = { enabled: false, aspectRatio: 1 };
    private letterboxElement: HTMLElement | null = null;

    constructor(events: Events, tooltips: TooltipSystem, parent: HTMLElement) {
        this.events = events;
        this._hidden = !!window.isFlutterApp;

        const { panel, body } = createPanel({
            title: '화각 설정',
            collapsible: true,
            collapsed: true,
            parent
        });

        this.dom = panel;
        this.dom.id = 'fov-panel';
        blockPointerEvents(this.dom);

        if (this._hidden) {
            this.dom.style.display = 'none';
        }

        // === Mode Selection ===
        const { value: modeValue } = createFormRow({ label: '화면 모드', parent: body });
        this.modeSelect = new SelectInput({
            options: [
                { value: 'LF 오픈 게이트', label: 'LF 오픈 게이트' },
                { value: 'LF 2.39:1', label: 'LF 2.39:1' },
                { value: 'LF 16:9', label: 'LF 16:9' }
            ],
            value: 'LF 오픈 게이트',
            parent: modeValue,
            onChange: (v) => {
                this.handleModeChange(v);
                this.updateFOV();
            }
        });

        // === Lens Selection ===
        const { value: lensValue } = createFormRow({ label: '렌즈 (mm)', parent: body });
        this.lensSelect = new SelectInput({
            options: [
                { value: '24', label: '24mm' },
                { value: '35', label: '35mm' },
                { value: '50', label: '50mm' },
                { value: '85', label: '85mm' },
                { value: '100', label: '100mm' },
                { value: '135', label: '135mm' }
            ],
            value: '24',
            parent: lensValue,
            onChange: () => this.updateFOV()
        });

        tooltips.register(this.modeSelect.dom, '화면 모드를 선택하세요', 'left');
        tooltips.register(this.lensSelect.dom, '렌즈 밀리수를 선택하세요', 'left');

        // Initialize letterbox
        this.initializeLetterbox();
        this.updateFOV();

        // Events
        events.on('fovCustomPanel.setVisible', (visible: boolean) => { this.hidden = !visible; });
        events.on('fovCustomPanel.toggleVisible', () => { this.hidden = !this._hidden; });
        events.function('fovCustomPanel.visible', () => !this._hidden);
    }

    private handleModeChange(mode: string) {
        switch (mode) {
            case 'LF 오픈 게이트': this.setLetterbox(false, 1); break;
            case 'LF 2.39:1': this.setLetterbox(true, 2.39); break;
            case 'LF 16:9': this.setLetterbox(true, 16 / 9); break;
        }
    }

    private updateFOV() {
        const mode = this.modeSelect.value;
        const lens = parseInt(this.lensSelect.value);
        const fovValue = FOV_MAPPING[mode]?.[lens];
        if (fovValue !== undefined) {
            this.events.fire('camera.setFov', fovValue);
        }
    }

    private initializeLetterbox() {
        if (!this.letterboxElement) {
            this.letterboxElement = document.createElement('div');
            this.letterboxElement.id = 'letterbox-overlay';
            Object.assign(this.letterboxElement.style, {
                position: 'fixed', top: '0', left: '0',
                width: '100%', height: '100%',
                pointerEvents: 'none', zIndex: '1000', display: 'none'
            });
            document.body.appendChild(this.letterboxElement);
        }
    }

    private setLetterbox(enabled: boolean, aspectRatio: number) {
        this.currentLetterbox = { enabled, aspectRatio };
        if (!this.letterboxElement) return;

        if (enabled) {
            this.letterboxElement.style.display = 'block';
            this.updateLetterboxSize(aspectRatio);
        } else {
            this.letterboxElement.style.display = 'none';
        }
    }

    private updateLetterboxSize(targetAspectRatio: number) {
        if (!this.letterboxElement) return;

        const w = window.innerWidth;
        const h = window.innerHeight;
        const windowAR = w / h;

        this.letterboxElement.innerHTML = '';

        const createBox = (css: string) => {
            const box = document.createElement('div');
            box.style.cssText = css;
            this.letterboxElement!.appendChild(box);
        };

        if (windowAR > targetAspectRatio) {
            const targetH = w / targetAspectRatio;
            const barH = Math.max(0, (h - targetH) / 2);
            if (barH > 0) {
                createBox(`position:absolute;top:0;left:0;width:100%;height:${barH}px;background:black`);
                createBox(`position:absolute;bottom:0;left:0;width:100%;height:${barH}px;background:black`);
            }
        } else {
            const targetW = h * targetAspectRatio;
            const barW = Math.max(0, (w - targetW) / 2);
            if (barW > 0) {
                createBox(`position:absolute;top:0;left:0;width:${barW}px;height:100%;background:black`);
                createBox(`position:absolute;top:0;right:0;width:${barW}px;height:100%;background:black`);
            }
        }
    }

    handleResize() {
        if (this.currentLetterbox.enabled) {
            this.updateLetterboxSize(this.currentLetterbox.aspectRatio);
        }
    }

    get hidden() { return this._hidden; }
    set hidden(v: boolean) {
        this._hidden = v;
        this.dom.style.display = v ? 'none' : '';
    }
}

export { FovPanel };
