import i18next from 'i18next';
import LanguageDetector from 'i18next-browser-languagedetector';
import Backend from 'i18next-http-backend';

// Flutter 환경에서는 HTTP backend로 번역 파일을 로드할 수 없으므로
// 번들에 직접 포함시켜 사용한다 (localizeInitMinimal에서 사용)
import koTranslation from '../../static/locales/ko.json';
import enTranslation from '../../static/locales/en.json';

/**
 * 웹 환경용 다국어 초기화
 * i18next-http-backend를 사용하여 HTTP fetch()로 번역 파일(static/locales/*.json)을 로드한다.
 * 주의: Flutter WebView의 로컬 파일 컨텍스트에서는 fetch()가 실패/타임아웃되므로 사용 불가
 */
const localizeInit = () => {
    return i18next
    .use(Backend)
    .use(LanguageDetector)
    .init({
        detection: {
            order: ['querystring', /* 'cookie', 'localStorage', 'sessionStorage',*/ 'navigator', 'htmlTag']
        },
        backend: {
            loadPath: './static/locales/{{lng}}.json'
        },
        supportedLngs: ['de', 'en', 'es', 'fr', 'ja', 'ko', 'pt-BR', 'ru', 'zh-CN'],
        fallbackLng: 'en',
        interpolation: {
            escapeValue: false
        }
    });
};

interface LocalizeOptions {
    ellipsis?: boolean;
}

const localize = (key: string, options?: LocalizeOptions): string => {
    let text = i18next.t(key);

    if (options?.ellipsis) text += '...';

    return text;
};

const getLocale = (): string => {
    return i18next.language || 'en';
};

const formatInteger = (value: number): string => {
    return new Intl.NumberFormat(getLocale(), {
        maximumFractionDigits: 0
    }).format(Math.round(value));
};

/**
 * Flutter 환경용 다국어 초기화 (HTTP 요청 없이 즉시 완료)
 *
 * - HTTP backend와 LanguageDetector를 사용하지 않음
 * - 번역 데이터를 JS 번들에 직접 포함 (ko, en만 약 27KB 추가)
 * - Flutter WebView에서 fetch() 타임아웃으로 인한 로딩 지연 문제를 해결
 * - 다른 언어가 필요하면 상단의 import와 resources에 추가하면 됨
 */
const localizeInitMinimal = () => {
    return i18next.init({
        lng: navigator.language?.startsWith('ko') ? 'ko' : 'en',
        fallbackLng: 'en',
        interpolation: { escapeValue: false },
        resources: {
            ko: { translation: koTranslation },
            en: { translation: enTranslation }
        }
    });
};

export { localizeInit, localizeInitMinimal, localize, formatInteger };
export type { LocalizeOptions };
