import { TranslateGizmo, Vec3 } from 'playcanvas';

import { BoxShape } from '../box-shape';
import { Events } from '../events';
import { Scene } from '../scene';
import { Splat } from '../splat';
import { NumericInput } from '../ui-new/input-components';

class BoxSelection {
    activate: () => void;
    deactivate: () => void;

    active = false;

    constructor(events: Events, scene: Scene, canvasContainer: { dom: HTMLElement }) {
        const box = new BoxShape();

        const gizmo = new TranslateGizmo(scene.camera.camera, scene.gizmoLayer);

        gizmo.on('render:update', () => {
            scene.forceRender = true;
        });

        gizmo.on('transform:move', () => {
            box.moved();
        });

        // ui
        const selectToolbar = document.createElement('div');
        selectToolbar.className = 'select-toolbar';
        selectToolbar.style.display = 'none';

        selectToolbar.addEventListener('pointerdown', (e) => {
            e.stopPropagation();
        });

        const createBtn = (text: string) => {
            const btn = document.createElement('button');
            btn.className = 'select-toolbar-button';
            btn.textContent = text;
            selectToolbar.appendChild(btn);
            return btn;
        };

        const setButton = createBtn('Set');
        const addButton = createBtn('Add');
        const removeButton = createBtn('Remove');

        const lenX = new NumericInput({ value: box.lenX, placeholder: 'LenX', precision: 2, step: 0.01, min: 0.01, parent: selectToolbar });
        lenX.dom.style.width = '80px';
        const lenY = new NumericInput({ value: box.lenY, placeholder: 'LenY', precision: 2, step: 0.01, min: 0.01, parent: selectToolbar });
        lenY.dom.style.width = '80px';
        const lenZ = new NumericInput({ value: box.lenZ, placeholder: 'LenZ', precision: 2, step: 0.01, min: 0.01, parent: selectToolbar });
        lenZ.dom.style.width = '80px';

        canvasContainer.dom.appendChild(selectToolbar);

        const apply = (op: 'set' | 'add' | 'remove') => {
            const p = box.pivot.getPosition();
            events.fire('select.byBox', op, [p.x, p.y, p.z, box.lenX, box.lenY, box.lenZ]);
        };

        setButton.addEventListener('pointerdown', (e) => {
            e.stopPropagation();
            apply('set');
        });
        addButton.addEventListener('pointerdown', (e) => {
            e.stopPropagation();
            apply('add');
        });
        removeButton.addEventListener('pointerdown', (e) => {
            e.stopPropagation();
            apply('remove');
        });
        lenX.dom.addEventListener('change', () => {
            box.lenX = lenX.value;
        });
        lenY.dom.addEventListener('change', () => {
            box.lenY = lenY.value;
        });
        lenZ.dom.addEventListener('change', () => {
            box.lenZ = lenZ.value;
        });

        events.on('camera.focalPointPicked', (details: { splat: Splat, position: Vec3 }) => {
            if (this.active) {
                box.pivot.setPosition(details.position);
                gizmo.attach([box.pivot]);
            }
        });

        const updateGizmoSize = () => {
            const { camera, canvas } = scene;
            if (camera.ortho) {
                gizmo.size = 1125 / canvas.clientHeight;
            } else {
                gizmo.size = 1200 / Math.max(canvas.clientWidth, canvas.clientHeight);
            }
        };
        updateGizmoSize();
        events.on('camera.resize', updateGizmoSize);
        events.on('camera.ortho', updateGizmoSize);

        this.activate = () => {
            this.active = true;
            scene.add(box);
            gizmo.attach([box.pivot]);
            selectToolbar.style.display = '';
        };

        this.deactivate = () => {
            selectToolbar.style.display = 'none';
            gizmo.detach();
            scene.remove(box);
            this.active = false;
        };
    }
}

export { BoxSelection };
