/**
 * Input Components
 * Pure HTML/CSS replacements for PCUI input widgets:
 * SliderInput, NumericInput, VectorInput, BooleanInput, SelectInput
 */

import { createElement, createContainer, createLabel } from './dom-helpers';

// ============================================
// NumericInput
// ============================================

export interface NumericInputOptions {
    value?: number;
    min?: number;
    max?: number;
    step?: number;
    precision?: number;
    placeholder?: string;
    enabled?: boolean;
    class?: string;
    parent?: HTMLElement;
    onChange?: (value: number) => void;
}

export class NumericInput {
    dom: HTMLDivElement;
    private _input: HTMLInputElement;
    private _value: number;
    private _precision: number;
    private _min?: number;
    private _max?: number;
    private _step: number;
    private _onChange?: (value: number) => void;

    constructor(options: NumericInputOptions = {}) {
        this._value = options.value ?? 0;
        this._precision = options.precision ?? 2;
        this._min = options.min;
        this._max = options.max;
        this._step = options.step ?? (1 / Math.pow(10, this._precision));
        this._onChange = options.onChange;

        // Wrapper
        const wrapper = document.createElement('div');
        wrapper.className = options.class ? `ax-numeric-wrap ${options.class}` : 'ax-numeric-wrap';

        // Input
        const input = createElement('input', {
            class: 'ax-input-number',
            attrs: {
                type: 'number',
                ...(this._min !== undefined ? { min: String(this._min) } : {}),
                ...(this._max !== undefined ? { max: String(this._max) } : {}),
                step: String(this._step),
                ...(options.placeholder ? { placeholder: options.placeholder } : {})
            }
        });
        input.value = this.formatValue(this._value);

        if (options.enabled === false) {
            input.disabled = true;
        }

        // Change handler
        input.addEventListener('change', () => {
            const newVal = parseFloat(input.value);
            if (!isNaN(newVal)) {
                this._setValue(this._clamp(newVal));
            } else {
                input.value = this.formatValue(this._value);
            }
        });

        input.addEventListener('focus', () => input.select());

        // Drag-to-adjust
        let dragging = false;
        let dragStartX = 0;
        let dragStartValue = 0;
        let hasMoved = false;

        input.addEventListener('pointerdown', (e: PointerEvent) => {
            if (input.disabled || e.button !== 0) return;
            // Only start drag if not clicking inside the input's spinner buttons
            dragging = true;
            hasMoved = false;
            dragStartX = e.clientX;
            dragStartValue = this._value;
            input.setPointerCapture(e.pointerId);
        });

        input.addEventListener('pointermove', (e: PointerEvent) => {
            if (!dragging) return;
            const dx = e.clientX - dragStartX;
            if (Math.abs(dx) > 2) {
                hasMoved = true;
                input.style.cursor = 'ew-resize';
                // Sensitivity: shift = fine, ctrl = coarse
                let sensitivity = this._step;
                if (e.shiftKey) sensitivity *= 0.1;
                if (e.ctrlKey) sensitivity *= 10;
                const newVal = this._clamp(dragStartValue + dx * sensitivity);
                this._setValue(newVal);
            }
        });

        const endDrag = (e: PointerEvent) => {
            if (!dragging) return;
            dragging = false;
            input.style.cursor = '';
            input.releasePointerCapture(e.pointerId);
            if (hasMoved) {
                // Prevent the click from focusing/selecting text after drag
                e.preventDefault();
            }
        };

        input.addEventListener('pointerup', endDrag);
        input.addEventListener('lostpointercapture', () => {
            dragging = false;
            input.style.cursor = '';
        });

        wrapper.appendChild(input);

        if (options.parent) {
            options.parent.appendChild(wrapper);
        }

        this.dom = wrapper;
        this._input = input;
    }

    private _clamp(v: number): number {
        if (this._min !== undefined && v < this._min) v = this._min;
        if (this._max !== undefined && v > this._max) v = this._max;
        return v;
    }

    private _setValue(v: number) {
        this._value = v;
        this._input.value = this.formatValue(v);
        this._onChange?.(v);
        // Dispatch change event for external listeners
        this._input.dispatchEvent(new Event('change', { bubbles: true }));
    }

    get value(): number {
        return this._value;
    }

    set value(v: number) {
        this._value = v;
        this._input.value = this.formatValue(v);
    }

    set enabled(v: boolean) {
        this._input.disabled = !v;
    }

    get enabled(): boolean {
        return !this._input.disabled;
    }

    private formatValue(v: number): string {
        return Number(v.toFixed(this._precision)).toString();
    }
}

// ============================================
// SliderInput
// ============================================

export interface SliderInputOptions {
    value?: number;
    min?: number;
    max?: number;
    step?: number;
    precision?: number;
    enabled?: boolean;
    class?: string;
    parent?: HTMLElement;
    onChange?: (value: number) => void;
    onSlideStart?: () => void;
    onSlideEnd?: () => void;
}

export class SliderInput {
    dom: HTMLDivElement;
    private _slider: HTMLInputElement;
    private _numInput: NumericInput;
    private _onChange?: (value: number) => void;
    private _onSlideStart?: () => void;
    private _onSlideEnd?: () => void;

    constructor(options: SliderInputOptions = {}) {
        this._onChange = options.onChange;
        this._onSlideStart = options.onSlideStart;
        this._onSlideEnd = options.onSlideEnd;

        const container = createContainer({
            class: options.class ? `ax-slider-container ${options.class}` : 'ax-slider-container',
            style: { display: 'flex', alignItems: 'center', gap: '8px', width: '100%' }
        });

        this._slider = createElement('input', {
            class: 'ax-slider',
            attrs: {
                type: 'range',
                min: String(options.min ?? 0),
                max: String(options.max ?? 1),
                step: String(options.step ?? 0.01),
                value: String(options.value ?? 0)
            },
            style: { flex: '1' }
        });

        this._numInput = new NumericInput({
            value: options.value ?? 0,
            min: options.min,
            max: options.max,
            step: options.step,
            precision: options.precision ?? 2,
            onChange: (v) => {
                this._slider.value = String(v);
                this._onChange?.(v);
            }
        });
        this._numInput.dom.style.width = '50px';

        // Sync slider → number
        this._slider.addEventListener('input', () => {
            const v = parseFloat(this._slider.value);
            this._numInput.value = v;
            this._onChange?.(v);
        });

        this._slider.addEventListener('pointerdown', () => {
            this._onSlideStart?.();
        });

        this._slider.addEventListener('pointerup', () => {
            this._onSlideEnd?.();
        });

        if (options.enabled === false) {
            this._slider.disabled = true;
            this._numInput.enabled = false;
        }

        container.appendChild(this._slider);
        container.appendChild(this._numInput.dom);

        if (options.parent) {
            options.parent.appendChild(container);
        }

        this.dom = container;
    }

    get value(): number {
        return parseFloat(this._slider.value);
    }

    set value(v: number) {
        this._slider.value = String(v);
        this._numInput.value = v;
    }

    set enabled(v: boolean) {
        this._slider.disabled = !v;
        this._numInput.enabled = v;
    }
}

// ============================================
// VectorInput (3-axis: X, Y, Z)
// ============================================

export interface VectorInputOptions {
    value?: number[];
    dimensions?: number;
    precision?: number;
    min?: number;
    max?: number;
    step?: number;
    enabled?: boolean;
    class?: string;
    parent?: HTMLElement;
    onChange?: (value: number[]) => void;
}

export class VectorInput {
    dom: HTMLDivElement;
    private _inputs: NumericInput[];
    private _dimensions: number;
    private _onChange?: (value: number[]) => void;

    constructor(options: VectorInputOptions = {}) {
        this._dimensions = options.dimensions ?? 3;
        this._onChange = options.onChange;
        const axisLabels = ['X', 'Y', 'Z', 'W'];
        const axisClasses = ['--x', '--y', '--z', '--w'];
        const initValue = options.value ?? new Array(this._dimensions).fill(0);

        const container = createContainer({
            class: options.class ? `ax-vector-input ${options.class}` : 'ax-vector-input'
        });

        this._inputs = [];
        for (let i = 0; i < this._dimensions; i++) {
            const axis = createContainer({ class: 'ax-vector-input__axis', parent: container });
            createLabel({
                text: axisLabels[i],
                class: `ax-vector-input__label ax-vector-input__label${axisClasses[i]}`,
                parent: axis
            });

            const idx = i;
            const input = new NumericInput({
                value: initValue[i],
                min: options.min,
                max: options.max,
                step: options.step ?? 0.01,
                precision: options.precision ?? 2,
                enabled: options.enabled,
                parent: axis,
                onChange: () => {
                    this._onChange?.(this.value);
                }
            });
            input.dom.style.flex = '1';
            this._inputs.push(input);
        }

        if (options.parent) {
            options.parent.appendChild(container);
        }

        this.dom = container;
    }

    get value(): number[] {
        return this._inputs.map(input => input.value);
    }

    set value(v: number[]) {
        for (let i = 0; i < this._dimensions && i < v.length; i++) {
            this._inputs[i].value = v[i];
        }
    }

    set enabled(v: boolean) {
        this._inputs.forEach(input => { input.enabled = v; });
    }

    getInput(index: number): NumericInput {
        return this._inputs[index];
    }
}

// ============================================
// BooleanInput (toggle or checkbox)
// ============================================

export interface BooleanInputOptions {
    value?: boolean;
    type?: 'checkbox' | 'toggle';
    enabled?: boolean;
    class?: string;
    parent?: HTMLElement;
    onChange?: (value: boolean) => void;
}

export class BooleanInput {
    dom: HTMLElement;
    private _input: HTMLInputElement;
    private _onChange?: (value: boolean) => void;

    constructor(options: BooleanInputOptions = {}) {
        this._onChange = options.onChange;
        const isToggle = options.type === 'toggle';

        if (isToggle) {
            // Use <label> so clicking the track toggles the hidden input
            const wrapper = document.createElement('label');
            wrapper.className = options.class ? `ax-toggle ${options.class}` : 'ax-toggle';
            this._input = createElement('input', {
                attrs: { type: 'checkbox' },
                parent: wrapper
            });
            createElement('span', { class: 'ax-toggle__track', parent: wrapper });
            this.dom = wrapper;
        } else {
            this._input = createElement('input', {
                class: options.class || '',
                attrs: { type: 'checkbox' }
            });
            this.dom = this._input;
        }

        if (options.value) {
            this._input.checked = true;
        }
        if (options.enabled === false) {
            this._input.disabled = true;
        }

        this._input.addEventListener('change', () => {
            this._onChange?.(this._input.checked);
        });

        if (options.parent) {
            options.parent.appendChild(this.dom);
        }
    }

    get value(): boolean {
        return this._input.checked;
    }

    set value(v: boolean) {
        this._input.checked = v;
    }

    set enabled(v: boolean) {
        this._input.disabled = !v;
    }
}

// ============================================
// SelectInput
// ============================================

export interface SelectOption {
    value: string;
    label: string;
}

export interface SelectInputOptions {
    options?: SelectOption[];
    value?: string;
    enabled?: boolean;
    class?: string;
    parent?: HTMLElement;
    onChange?: (value: string) => void;
}

export class SelectInput {
    dom: HTMLSelectElement;
    private _onChange?: (value: string) => void;

    constructor(options: SelectInputOptions = {}) {
        this._onChange = options.onChange;

        const select = createElement('select', {
            class: options.class ? `ax-select ${options.class}` : 'ax-select'
        });

        if (options.options) {
            options.options.forEach(opt => {
                const optEl = createElement('option', {
                    text: opt.label,
                    attrs: { value: opt.value },
                    parent: select
                });
            });
        }

        if (options.value !== undefined) {
            select.value = options.value;
        }

        if (options.enabled === false) {
            select.disabled = true;
        }

        select.addEventListener('change', () => {
            this._onChange?.(select.value);
        });

        if (options.parent) {
            options.parent.appendChild(select);
        }

        this.dom = select;
    }

    get value(): string {
        return this.dom.value;
    }

    set value(v: string) {
        this.dom.value = v;
    }

    set enabled(v: boolean) {
        this.dom.disabled = !v;
    }

    setOptions(opts: SelectOption[]) {
        this.dom.innerHTML = '';
        opts.forEach(opt => {
            createElement('option', {
                text: opt.label,
                attrs: { value: opt.value },
                parent: this.dom
            });
        });
    }
}

// ============================================
// TextInput
// ============================================

export interface TextInputOptions {
    value?: string;
    placeholder?: string;
    enabled?: boolean;
    class?: string;
    parent?: HTMLElement;
    onChange?: (value: string) => void;
    onEnter?: (value: string) => void;
}

export class TextInput {
    dom: HTMLInputElement;
    private _onChange?: (value: string) => void;

    constructor(options: TextInputOptions = {}) {
        this._onChange = options.onChange;

        const input = createElement('input', {
            class: options.class ? `ax-input ${options.class}` : 'ax-input',
            attrs: {
                type: 'text',
                ...(options.placeholder ? { placeholder: options.placeholder } : {})
            }
        });

        if (options.value) input.value = options.value;
        if (options.enabled === false) input.disabled = true;

        input.addEventListener('change', () => {
            this._onChange?.(input.value);
        });

        if (options.onEnter) {
            input.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    options.onEnter!(input.value);
                }
            });
        }

        if (options.parent) {
            options.parent.appendChild(input);
        }

        this.dom = input;
    }

    get value(): string {
        return this.dom.value;
    }

    set value(v: string) {
        this.dom.value = v;
    }

    set enabled(v: boolean) {
        this.dom.disabled = !v;
    }
}
