/**
 * Popup (New)
 * Pure HTML/CSS modal dialog system replacing PCUI Popup.
 * Supports: error, info, yesno, okcancel types.
 */

import { localize } from '../ui/localization';
import { createContainer, createElement, createLabel, createButton } from './dom-helpers';

interface ShowOptions {
    type: 'error' | 'info' | 'yesno' | 'okcancel';
    message: string;
    header?: string;
    link?: string;
}

class NewPopup {
    dom: HTMLDivElement;
    private _dialog: HTMLDivElement;
    private _header: HTMLSpanElement;
    private _text: HTMLDivElement;
    private _linkRow: HTMLDivElement;
    private _linkText: HTMLSpanElement;
    private _okBtn: HTMLButtonElement;
    private _cancelBtn: HTMLButtonElement;
    private _yesBtn: HTMLButtonElement;
    private _noBtn: HTMLButtonElement;
    private _hidden = true;

    constructor() {
        // Overlay
        this.dom = createContainer({
            id: 'popup',
            class: 'ax-modal-overlay',
            style: { display: 'none' }
        });
        this.dom.tabIndex = -1;

        // Dialog
        this._dialog = createContainer({ class: 'ax-modal', parent: this.dom });
        this._dialog.style.minWidth = '360px';
        this._dialog.style.maxWidth = '500px';

        // Header
        const headerEl = createContainer({ class: 'ax-modal__header', parent: this._dialog });
        this._header = createLabel({ parent: headerEl });

        // Body
        const bodyEl = createContainer({ class: 'ax-modal__body', parent: this._dialog });
        this._text = createContainer({ parent: bodyEl });
        this._text.style.whiteSpace = 'pre-wrap';
        this._text.style.wordBreak = 'break-word';

        // Link row
        this._linkRow = createContainer({
            parent: bodyEl,
            style: { display: 'none', alignItems: 'center', gap: '8px', marginTop: '8px' }
        });
        this._linkText = createLabel({ parent: this._linkRow });
        this._linkText.style.flex = '1';
        this._linkText.style.overflow = 'hidden';
        this._linkText.style.textOverflow = 'ellipsis';

        // Footer
        const footer = createContainer({ class: 'ax-modal__footer', parent: this._dialog });
        this._okBtn = createButton({ text: localize('popup.ok'), variant: 'primary', parent: footer });
        this._cancelBtn = createButton({ text: localize('popup.cancel'), parent: footer });
        this._yesBtn = createButton({ text: localize('popup.yes'), variant: 'primary', parent: footer });
        this._noBtn = createButton({ text: localize('popup.no'), parent: footer });

        // Prevent dialog clicks from closing
        this._dialog.addEventListener('click', (e) => e.stopPropagation());
    }

    show(options: ShowOptions): Promise<{ action: string; value?: string }> {
        this._header.textContent = options.header || '';
        this._text.textContent = options.message;

        const { type, link } = options;

        // Show/hide buttons based on type
        this._okBtn.style.display = type === 'yesno' ? 'none' : '';
        this._cancelBtn.style.display = type === 'okcancel' ? '' : 'none';
        this._yesBtn.style.display = type === 'yesno' ? '' : 'none';
        this._noBtn.style.display = type === 'yesno' ? '' : 'none';

        // Error styling
        this._text.style.color = type === 'error' ? 'var(--ax-error)' : 'var(--ax-text-primary)';

        // Link
        if (link) {
            this._linkRow.style.display = 'flex';
            this._linkText.innerHTML = `<a href='${link}' target='_blank' style='color: var(--ax-accent)'>${link}</a>`;
        } else {
            this._linkRow.style.display = 'none';
        }

        this.dom.style.display = '';
        this._hidden = false;
        this.dom.focus();

        return new Promise<{ action: string; value?: string }>((resolve) => {
            const close = (action: string) => {
                this.hide();
                cleanup();
                resolve({ action });
            };

            const onOk = () => close('ok');
            const onCancel = () => close('cancel');
            const onYes = () => close('yes');
            const onNo = () => close('no');
            const onOverlay = () => {
                if (type === 'info' && !link) close('cancel');
            };
            const onKey = (e: KeyboardEvent) => {
                if (e.key === 'Escape') close('cancel');
                if (e.key === 'Enter') close(type === 'yesno' ? 'yes' : 'ok');
            };

            this._okBtn.addEventListener('click', onOk);
            this._cancelBtn.addEventListener('click', onCancel);
            this._yesBtn.addEventListener('click', onYes);
            this._noBtn.addEventListener('click', onNo);
            this.dom.addEventListener('click', onOverlay);
            this.dom.addEventListener('keydown', onKey);

            const cleanup = () => {
                this._okBtn.removeEventListener('click', onOk);
                this._cancelBtn.removeEventListener('click', onCancel);
                this._yesBtn.removeEventListener('click', onYes);
                this._noBtn.removeEventListener('click', onNo);
                this.dom.removeEventListener('click', onOverlay);
                this.dom.removeEventListener('keydown', onKey);
            };
        });
    }

    hide() {
        this.dom.style.display = 'none';
        this._hidden = true;
    }

    get hidden() { return this._hidden; }
    set hidden(v: boolean) {
        this._hidden = v;
        this.dom.style.display = v ? 'none' : '';
    }
}

export { ShowOptions, NewPopup };
