/**
 * Spinner (New)
 * Pure HTML/CSS replacement for PCUI Spinner.
 */

import { createContainer } from './dom-helpers';

class NewSpinner {
    dom: HTMLDivElement;
    private _hidden = true;

    constructor() {
        this.dom = createContainer({
            id: 'spinner-container',
            class: 'ax-modal-overlay',
            style: { display: 'none', backgroundColor: 'rgba(0,0,0,0.3)' }
        });
        this.dom.tabIndex = 0;

        const spinner = createContainer({ class: 'ax-spinner', parent: this.dom });
        createContainer({ class: 'ax-spinner__circle', parent: spinner });

        this.dom.addEventListener('keydown', (event) => {
            if (this._hidden) return;
            event.stopPropagation();
            event.preventDefault();
        });
    }

    get hidden() { return this._hidden; }
    set hidden(v: boolean) {
        this._hidden = v;
        this.dom.style.display = v ? 'none' : '';
    }
}

export { NewSpinner };
