/**
 * ScenePanel (New)
 * Pure HTML/CSS replacement for PCUI ScenePanel + SplatList + Transform.
 * Placed in the left panel area.
 */

import { SplatRenameOp } from '../edit-ops';
import { Element, ElementType } from '../element';
import { Events } from '../events';
import { Splat } from '../splat';
import { localize } from '../ui/localization';
import { createContainer, createElement, createLabel, createPanel, blockPointerEvents } from './dom-helpers';
import { TooltipSystem } from './tooltip-system';

// SVG imports
import soloSvg from '../ui/svg/solo.svg';
import sceneImportSvg from '../ui/svg/import.svg';
import sceneNewSvg from '../ui/svg/new.svg';
import deleteSvg from '../ui/svg/delete.svg';
import shownSvg from '../ui/svg/shown.svg';
import hiddenSvg from '../ui/svg/hidden.svg';

const decodeSvg = (svgDataUri: string): string => {
    try {
        return decodeURIComponent(svgDataUri.substring('data:image/svg+xml,'.length));
    } catch {
        return '';
    }
};

// ============================================
// SplatItem - individual item in splat list
// ============================================
class SplatItem {
    dom: HTMLDivElement;
    private _nameEl: HTMLSpanElement;
    private _visibleBtn: HTMLSpanElement;
    private _invisibleBtn: HTMLSpanElement;
    private _selected = false;
    private _visible = true;
    private _listeners: Map<string, Function[]> = new Map();

    constructor(name: string, events: Events) {
        this.dom = createContainer({ class: 'ax-splat-list__item' });
        this.dom.classList.add('visible');

        // Name
        this._nameEl = createLabel({
            text: name,
            class: 'ax-splat-list__item__name',
            parent: this.dom
        });

        // Visible icon
        this._visibleBtn = createElement('span', {
            class: 'ax-splat-list__item__visibility',
            html: decodeSvg(shownSvg),
            parent: this.dom
        });

        // Invisible icon (hidden initially)
        this._invisibleBtn = createElement('span', {
            class: 'ax-splat-list__item__visibility',
            html: decodeSvg(hiddenSvg),
            parent: this.dom
        });
        this._invisibleBtn.style.display = 'none';

        // Delete button
        const deleteBtn = createElement('span', {
            class: 'ax-splat-list__item__visibility',
            html: decodeSvg(deleteSvg),
            parent: this.dom,
            style: { opacity: '0.3' }
        });
        deleteBtn.addEventListener('mouseenter', () => { deleteBtn.style.opacity = '1'; });
        deleteBtn.addEventListener('mouseleave', () => { deleteBtn.style.opacity = '0.3'; });

        // Click handlers
        this._visibleBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            this.visible = false;
        });

        this._invisibleBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            this.visible = true;
        });

        deleteBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            this._emit('removeClicked');
        });

        // Rename on double-click
        this._nameEl.addEventListener('dblclick', (e) => {
            e.stopPropagation();
            const input = createElement('input', {
                class: 'ax-input',
                attrs: { type: 'text', value: this._nameEl.textContent || '' },
                style: { flex: '1', fontSize: '11px' }
            }) as HTMLInputElement;

            this._nameEl.style.display = 'none';
            this.dom.insertBefore(input, this._visibleBtn);
            input.focus();
            input.select();

            const finish = () => {
                const newName = input.value;
                input.remove();
                this._nameEl.style.display = '';
                this._emit('rename', newName);
            };

            input.addEventListener('blur', finish);
            input.addEventListener('keydown', (ev) => {
                if (ev.key === 'Enter') input.blur();
                if (ev.key === 'Escape') {
                    input.value = this._nameEl.textContent || '';
                    input.blur();
                }
            });
        });

        // Click to select
        this.dom.addEventListener('click', () => {
            this._emit('click');
        });
    }

    get name(): string {
        return this._nameEl.textContent || '';
    }

    set name(v: string) {
        this._nameEl.textContent = v;
    }

    get selected(): boolean {
        return this._selected;
    }

    set selected(v: boolean) {
        if (this._selected !== v) {
            this._selected = v;
            this.dom.classList.toggle('selected', v);
        }
    }

    get visible(): boolean {
        return this._visible;
    }

    set visible(v: boolean) {
        if (this._visible !== v) {
            this._visible = v;
            this._visibleBtn.style.display = v ? '' : 'none';
            this._invisibleBtn.style.display = v ? 'none' : '';
            this.dom.classList.toggle('visible', v);
            this._emit(v ? 'visible' : 'invisible');
        }
    }

    on(event: string, fn: Function) {
        if (!this._listeners.has(event)) this._listeners.set(event, []);
        this._listeners.get(event)!.push(fn);
    }

    private _emit(event: string, ...args: any[]) {
        const fns = this._listeners.get(event);
        if (fns) fns.forEach(fn => fn(...args));
    }

    destroy() {
        this.dom.remove();
        this._listeners.clear();
    }
}

// ============================================
// ScenePanel
// ============================================
class NewScenePanel {
    dom: HTMLDivElement;

    constructor(events: Events, tooltips: TooltipSystem, container: HTMLDivElement) {
        this.dom = container;
        const panel = container;

        blockPointerEvents(panel);

        // === Scene Manager Section ===
        const soloBtn = createElement('button', {
            class: 'ax-btn--icon',
            html: decodeSvg(soloSvg),
            style: { width: '24px', height: '24px' }
        });

        const importBtn = createElement('button', {
            class: 'ax-btn--icon',
            html: decodeSvg(sceneImportSvg),
            style: { width: '24px', height: '24px' }
        });

        const newBtn = createElement('button', {
            class: 'ax-btn--icon',
            html: decodeSvg(sceneNewSvg),
            style: { width: '24px', height: '24px' }
        });

        const { panel: sceneSection, body: sceneBody } = createPanel({
            title: localize('panel.scene-manager'),
            collapsible: true,
            parent: panel,
            headerExtra: [soloBtn, importBtn, newBtn]
        });

        // Splat list container
        const splatListEl = createContainer({
            class: 'ax-splat-list',
            parent: sceneBody,
            style: { maxHeight: '200px', overflowY: 'auto' }
        });

        // Solo toggle
        let soloActive = false;
        soloBtn.addEventListener('click', () => {
            soloActive = !soloActive;
            soloBtn.classList.toggle('active', soloActive);
            events.fire('scene.solo', soloActive);
        });

        importBtn.addEventListener('click', async () => {
            await events.invoke('scene.import');
        });

        newBtn.addEventListener('click', () => {
            events.invoke('doc.new');
        });

        tooltips.register(soloBtn, localize('tooltip.scene.solo'), 'bottom');
        tooltips.register(importBtn, 'Import Scene', 'bottom');
        tooltips.register(newBtn, 'New Scene', 'bottom');

        // === Splat List Logic ===
        const items = new Map<Splat, SplatItem>();
        let soloMode = false;
        const savedVisibility = new Map<Splat, boolean>();

        events.on('scene.elementAdded', (element: Element) => {
            if (element.type === ElementType.splat) {
                const splat = element as Splat;
                const item = new SplatItem(splat.name, events);
                splatListEl.appendChild(item.dom);
                items.set(splat, item);

                if (soloMode) {
                    savedVisibility.set(splat, splat.visible);
                    splat.visible = false;
                }

                item.on('visible', () => {
                    splat.visible = true;
                    if (!events.invoke('selection')) {
                        events.fire('selection', splat);
                    }
                });
                item.on('invisible', () => { splat.visible = false; });
                item.on('rename', (value: string) => {
                    events.fire('edit.add', new SplatRenameOp(splat, value));
                });
                item.on('click', () => {
                    if (soloMode && !splat.visible) {
                        splat.visible = true;
                    }
                    events.fire('selection', splat);
                });
                item.on('removeClicked', async () => {
                    const result = await events.invoke('showPopup', {
                        type: 'yesno',
                        header: 'Remove Splat',
                        message: `Are you sure you want to remove '${splat.name}' from the scene? This operation can not be undone.`
                    });
                    if (result?.action === 'yes') {
                        splat.destroy();
                    }
                });
            }
        });

        events.on('scene.elementRemoved', (element: Element) => {
            if (element.type === ElementType.splat) {
                const splat = element as Splat;
                const item = items.get(splat);
                if (item) {
                    item.destroy();
                    items.delete(splat);
                }
                savedVisibility.delete(splat);
            }
        });

        events.on('selection.changed', (selection: Splat, prev: Splat) => {
            items.forEach((value, key) => {
                value.selected = key === selection;
            });

            if (soloMode) {
                if (prev) prev.visible = false;
                if (selection) selection.visible = true;
            }
        });

        events.on('scene.solo', (value: boolean) => {
            soloMode = value;
            const selection = events.invoke('selection') as Splat;

            if (soloMode) {
                items.forEach((item, splat) => {
                    savedVisibility.set(splat, splat.visible);
                    splat.visible = splat === selection;
                });
            } else {
                items.forEach((item, splat) => {
                    const wasVisible = savedVisibility.get(splat);
                    splat.visible = wasVisible !== undefined ? wasVisible : true;
                });
                savedVisibility.clear();
            }
        });

        events.on('splat.name', (splat: Splat) => {
            const item = items.get(splat);
            if (item) item.name = splat.name;
        });

        events.on('splat.visibility', (splat: Splat) => {
            const item = items.get(splat);
            if (item) item.visible = splat.visible;
        });

        // Transform is now in SecondaryToolbar
    }
}

export { NewScenePanel };
